import Foundation
import AVFoundation
import UniformTypeIdentifiers
import Network

private let logScope = "[avassetresourceloader]"

public protocol UPlayerAVAssetResourceLoaderDelegate: AnyObject {
    func getPlaylist(source: UPlayerAVAssetResourceLoaderProtocol, url: URL) -> String?
}

public protocol UPlayerMediaResourceProcessor: AnyObject {
    func processMediaData(_ data: Data, sourceURL: URL) async throws -> Data
    func processMediaData(_ data: Data, sourceURL: URL, sourceOffset: Int64) async throws -> Data
}

public extension UPlayerMediaResourceProcessor {
    func processMediaData(_ data: Data, sourceURL: URL, sourceOffset: Int64) async throws -> Data {
        try await processMediaData(data, sourceURL: sourceURL)
    }
}

public protocol UPlayerAVAssetResourceLoaderTranscodingDelegate: AnyObject {
    func getAudioTranscoder(source: UPlayerAVAssetResourceLoaderProtocol) -> UPlayerAudioTranscoderProtocol?
}

public protocol UPlayerAVAssetResourceLoaderProtocol: AVAssetResourceLoaderDelegate {
    var dataDelegate: UPlayerAVAssetResourceLoaderDelegate? { get set }
    var transcoderDelegate: UPlayerAVAssetResourceLoaderTranscodingDelegate? { get set }
    var mediaRequestHeader: [String: Any]? { get set }
    var mediaResourceProcessor: UPlayerMediaResourceProcessor? { get set }
}

internal final class UPlayerAVAssetResourceLoader: NSObject, UPlayerAVAssetResourceLoaderProtocol {
    
    public weak var dataDelegate: UPlayerAVAssetResourceLoaderDelegate?
    public weak var transcoderDelegate: UPlayerAVAssetResourceLoaderTranscodingDelegate?
    public var mediaRequestHeader: [String: Any]?
    public weak var mediaResourceProcessor: UPlayerMediaResourceProcessor?
    private let transcodedCache = NSCache<NSString, NSData>()
    private let cencProxy = LocalCENCProxy()
    private lazy var persistentMediaCacheManager: UPlayerMediaCacheManager? = {
        return UPlayerMediaCacheManager(rootDirectory: commonCacheDirectory)
    }()
    
    override init() {
        super.init()
        transcodedCache.countLimit = 64
        transcodedCache.totalCostLimit = 32 * 1024 * 1024
    }

    deinit { cencProxy.stop() }
    
    public func resourceLoader(_ resourceLoader: AVAssetResourceLoader, shouldWaitForLoadingOfRequestedResource loadingRequest: AVAssetResourceLoadingRequest) -> Bool {

        guard let url = loadingRequest.request.url else {
            loadingRequest.finishLoading(with: UPlayerError.assetLoadingFailed)
            return true
        }

        log("\(logScope) request, \(url.absoluteString)", loggingLevel: .info)

        switch requestMode(url) {
        case "audio-transcode-init":
            handleAudioInitialization(url: url,
                                      loadingRequest: loadingRequest)
        case "audio-transcode":
            handleAudioTranscode(url: url,
                                 loadingRequest: loadingRequest)

        case "cenc-init", "cenc-segment":
            // These URLs are generated by UPlayer.rewriteHLSForMediaProcessor.
            // They must reach the CENC byte processor; otherwise AVFoundation
            // receives the in-memory playlist text for an .m4s request.
            handleCENC(url: url,
                       loadingRequest: loadingRequest)

        case "video-init", "video-segment", "audio-init", "audio-segment":
            handleCachedMediaFragment(url: url,
                                      loadingRequest: loadingRequest)
        default:
            handlePlaylist(url: url,
                           loadingRequest: loadingRequest)
        }

        return true
    }
    
    public func resourceLoader(_ resourceLoader: AVAssetResourceLoader, didCancel loadingRequest: AVAssetResourceLoadingRequest) {}
}


extension UPlayerAVAssetResourceLoader {
    fileprivate func requestMode(_ url: URL) -> String? {
        URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems?.first {
            $0.name == "mode"
        }?.value
    }
    
    fileprivate func originalCodec(from url: URL) -> String? {
        URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems?.first {
            $0.name == "codec"
        }?.value
    }

    fileprivate func cachedFileURL(from url: URL) -> URL? {
        guard let path = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems?.first(where: {
            $0.name == "cacheFile"
        })?.value, !path.isEmpty else {
            return nil
        }
        return URL(fileURLWithPath: path)
    }
    
    fileprivate func originalHTTPURL(from url: URL) -> URL? {
        let original = url.absoluteString
        guard let schemeRange = original.range(of: "://") else {
            return nil
        }
        
        let scheme = String(original[..<schemeRange.lowerBound]).lowercased()
        let transport = (scheme == "http") ? "http://" : "https://"
        let value = transport + original[schemeRange.upperBound...]
        guard let questionMark = value.firstIndex(of: "?") else {
            return URL(string: value)
        }
        
        let base = String(value[..<questionMark])
        let queryStart = value.index(after: questionMark)
        let rawQuery = String(value[queryStart...])
        
        let filteredQuery = rawQuery.split(separator: "&", omittingEmptySubsequences: false).filter { rawItem in
            let name = rawItem.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false).first.map(String.init) ?? ""
            return name != "mode" && name != "codec" && name != "cacheFile"
        }.joined(separator: "&")
        
        let result = filteredQuery.isEmpty ? base : "\(base)?\(filteredQuery)"
        return URL(string: result)
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func handleCENC(url: URL, loadingRequest: AVAssetResourceLoadingRequest) {
        Task { [weak self] in
            guard let self else { return }
            do {
                guard let realURL = originalHTTPURL(from: url) else {
                    throw UPlayerError.assetLoadingFailed
                }

                let start = max(
                    Int64(0),
                    loadingRequest.dataRequest?.requestedOffset ?? 0,
                    loadingRequest.dataRequest?.currentOffset ?? 0
                )
                let requestedLength = Int64(
                    loadingRequest.dataRequest?.requestedLength ?? 0
                )

                // HLS EXT-X-MAP / EXT-X-BYTERANGE requests carry the physical
                // MP4 byte range in AVAssetResourceLoadingDataRequest. Download
                // only that range instead of the entire media resource.
                let range: ClosedRange<Int64>? = {
                    guard requestedLength > 0,
                          start <= Int64.max - requestedLength else {
                        return nil
                    }
                    let end = start + requestedLength - 1
                    return end >= start ? start...end : nil
                }()

                let fetched = try await downloadRange(url: realURL, range: range)
                guard !fetched.data.isEmpty else { throw UPlayerError.emptyDownload }

                // The CENC processor needs the absolute position of this slice
                // when tfhd/trun/saio contain file-relative offsets.
                let processed = try await mediaResourceProcessor?.processMediaData(
                    fetched.data,
                    sourceURL: realURL,
                    sourceOffset: fetched.startOffset
                ) ?? fetched.data

                guard !processed.isEmpty else { throw UPlayerError.emptyDownload }

                respondRange(
                    data: processed,
                    rangeStart: fetched.startOffset,
                    totalLength: fetched.totalLength,
                    uti: UTType(filenameExtension: "mp4")?.identifier ?? "public.mpeg-4",
                    mimeType: "video/mp4",
                    loadingRequest: loadingRequest
                )
            } catch {
                let mode = requestMode(url) ?? "unknown"
                log("\(logScope) CENC \(mode) loading/processing failed: \(error)", loggingLevel: .error)
                loadingRequest.finishLoading(with: error)
            }
        }
    }
}

private extension UPlayerAVAssetResourceLoader {
    struct RangeDownload {
        let data: Data
        let startOffset: Int64
        let totalLength: Int64?
    }

    func downloadRange(url: URL, range: ClosedRange<Int64>?) async throws -> RangeDownload {
        var request = URLRequest(
            url: url,
            cachePolicy: .reloadIgnoringLocalCacheData,
            timeoutInterval: 30
        )

        for (field, value) in mediaRequestHeader ?? [:] {
            request.setValue(String(describing: value), forHTTPHeaderField: field)
        }

        if let range {
            request.setValue(
                "bytes=\(range.lowerBound)-\(range.upperBound)",
                forHTTPHeaderField: "Range"
            )
        }

        let (rawData, response) = try await URLSession.shared.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw UPlayerError.invalidHTTPResponse(-1)
        }

        guard (200...299).contains(http.statusCode) else {
            throw UPlayerError.invalidHTTPResponse(http.statusCode)
        }

        let contentRange = http.value(forHTTPHeaderField: "Content-Range")
        let parsed = parseContentRange(contentRange)

        if http.statusCode == 206, let range {
            let actualStart = parsed?.start ?? range.lowerBound
            let expectedCount = Int64(range.upperBound - range.lowerBound + 1)

            let skip = max(Int64(0), range.lowerBound - actualStart)
            let available = Int64(rawData.count)
            let count = min(expectedCount, max(Int64(0), available - skip))

            guard skip >= 0,
                  count > 0,
                  skip <= available else {
                throw UPlayerError.emptyDownload
            }

            let data = rawData.subdata(
                in: Int(skip)..<Int(skip + count)
            )
            return RangeDownload(
                data: data,
                startOffset: range.lowerBound,
                totalLength: parsed?.total
            )
        }

        // Some CDNs ignore Range and return the whole MP4 with HTTP 200.
        // Slice it locally so the CENC offsets remain relative to the requested
        // physical range.
        if let range {
            let total = parsed?.total
                ?? Int64(http.value(forHTTPHeaderField: "Content-Length").flatMap(Int64.init) ?? Int64(rawData.count))
            let start = max(Int64(0), range.lowerBound)
            guard start < Int64(rawData.count) else {
                throw UPlayerError.emptyDownload
            }

            let maxCount = Int64(rawData.count) - start
            let requested = range.upperBound - range.lowerBound + 1
            let count = min(requested, maxCount)
            guard count > 0 else { throw UPlayerError.emptyDownload }

            return RangeDownload(
                data: rawData.subdata(in: Int(start)..<Int(start + count)),
                startOffset: range.lowerBound,
                totalLength: total
            )
        }

        let total = parsed?.total
            ?? Int64(http.value(forHTTPHeaderField: "Content-Length").flatMap(Int64.init) ?? Int64(rawData.count))
        return RangeDownload(data: rawData, startOffset: 0, totalLength: total)
    }

    func parseContentRange(_ value: String?) -> (start: Int64, end: Int64, total: Int64?)? {
        guard let value else { return nil }
        let parts = value.split(separator: " ", maxSplits: 1).map(String.init)
        guard parts.count == 2 else { return nil }

        let rangeAndTotal = parts[1].split(separator: "/", maxSplits: 1).map(String.init)
        guard let bounds = rangeAndTotal.first?.split(separator: "-", maxSplits: 1),
              bounds.count == 2,
              let start = Int64(bounds[0]),
              let end = Int64(bounds[1]) else {
            return nil
        }

        let total: Int64?
        if let totalPart = rangeAndTotal.dropFirst().first,
           totalPart != "*" {
            total = Int64(totalPart)
        } else {
            total = nil
        }

        return (start, end, total)
    }

    func respondRange(
        data: Data,
        rangeStart: Int64,
        totalLength: Int64?,
        uti: String,
        mimeType: String,
        loadingRequest: AVAssetResourceLoadingRequest
    ) {
        let contentLength = totalLength ?? (rangeStart + Int64(data.count))

        if let info = loadingRequest.contentInformationRequest {
            info.contentType = uti
            info.contentLength = contentLength
            info.isByteRangeAccessSupported = true
        }

        if let requestURL = loadingRequest.request.url {
            loadingRequest.response = HTTPURLResponse(
                url: requestURL,
                statusCode: 206,
                httpVersion: "HTTP/1.1",
                headerFields: [
                    "Content-Type": mimeType,
                    "Content-Length": "\(data.count)",
                    "Content-Range": "bytes \(rangeStart)-\(rangeStart + Int64(data.count) - 1)/\(contentLength)",
                    "Accept-Ranges": "bytes"
                ]
            )
        }

        loadingRequest.dataRequest?.respond(with: data)
        loadingRequest.finishLoading()
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func handleCachedMediaFragment(url: URL, loadingRequest: AVAssetResourceLoadingRequest) {
        Task { [weak self] in
            guard let self else { return }

            do {
                guard let realURL = originalHTTPURL(from: url),
                      let localURL = cachedFileURL(from: url) else {
                    throw UPlayerError.assetLoadingFailed
                }

                let data: Data
                if FileManager.default.fileExists(atPath: localURL.path) {
                    data = try Data(contentsOf: localURL, options: .mappedIfSafe)
                    persistentMediaCacheManager?.touch(fileURL: localURL)
                    log("\(logScope) media cache hit, mode: \(requestMode(url) ?? "unknown"), source: \(realURL.absoluteString), file: \(localURL.path), bytes: \(data.count)", loggingLevel: .debug)
                } else {
                    // Cache directories may be purged by the OS. Preserve playback by
                    // falling back to the original network resource.
                    log("\(logScope) cached media file missing, fallback to network: \(localURL.path)", loggingLevel: .debug)
                    data = try await download(url: realURL)
                }

                guard !data.isEmpty else {
                    throw UPlayerError.emptyDownload
                }

                let mimeType = (requestMode(url)?.hasPrefix("audio-") == true) ? "audio/mp4" : "video/mp4"
                respondRedirectedMedia(data: data,
                                       realURL: realURL,
                                       mimeType: mimeType,
                                       loadingRequest: loadingRequest)
            } catch {
                log("\(logScope) cached media loading failed for \(url.absoluteString), \(error)", loggingLevel: .error)
                loadingRequest.finishLoading(with: error)
            }
        }
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func handleAudioInitialization(url: URL, loadingRequest: AVAssetResourceLoadingRequest) {
        Task { [weak self] in
            guard let self else {
                return
            }
            
            do {
                let cacheKey = "init|\(originalCodec(from: url) ?? "")" as NSString
                guard let realURL = originalHTTPURL(from: url) else {
                    throw UPlayerError.assetLoadingFailed
                }
                
                if let cached = transcodedCache.object(forKey: cacheKey) {
                    respondRedirectedMedia(data: cached as Data,
                                           realURL: realURL,
                                           mimeType: "audio/mp4",
                                           loadingRequest: loadingRequest)
                    return
                }
                
                guard let transcoder = transcoderDelegate?.getAudioTranscoder(source: self) else {
                    throw UPlayerError.aacEncodongFailed8
                }
                
                let codec = originalCodec(from: url)
                guard let result = try await transcoder.makeInitializationSegment(originalCodec: codec) else {
                    throw UPlayerError.aacEncodongFailed7
                }
                
                guard result.format == .fragmentedMP4, !result.data.isEmpty else {
                    throw UPlayerError.aacEncodongFailed7
                }
                
                log("\(logScope) AAC init generated codec=\(codec ?? "unknown") bytes=\(result.data.count) format=\(result.format) contentType=\(result.contentType)",
                    loggingLevel: .debug)
                
                dumpTopLevelMP4Boxes(result.data, prefix: "AAC init")
                
                transcodedCache.setObject(result.data as NSData,
                                          forKey: cacheKey,
                                          cost: result.data.count)
                respondRedirectedMedia(data: result.data,
                                       realURL: realURL,
                                       mimeType: "audio/mp4",
                                       loadingRequest: loadingRequest)
            } catch {
                log("\(logScope) init transcoding failed: \(error)", loggingLevel: .error)
                loadingRequest.finishLoading(with: error)
            }
        }
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func handleAudioTranscode(url: URL, loadingRequest: AVAssetResourceLoadingRequest) {
        Task { [weak self] in
            guard let self else {
                return
            }
            
            do {
                guard let sourceURL = originalHTTPURL(from: url) else {
                    throw UPlayerError.assetLoadingFailed
                }
            
                let cacheKey = url.absoluteString as NSString
                if let cached = transcodedCache.object(forKey: cacheKey) {
                    log("\(logScope) audio cache hit", loggingLevel: .debug)
                    
                    respondRedirectedMedia(data: cached as Data,
                                           realURL: sourceURL,
                                           mimeType: "audio/mp4",
                                           loadingRequest: loadingRequest)
                    return
                }
                
                guard let transcoder = transcoderDelegate?.getAudioTranscoder(source: self) else {
                    throw UPlayerError.aacEncodongFailed8
                }
                
                let codec = originalCodec(from: url)
                log("\(logScope) transcoding request: \(url.absoluteString)", loggingLevel: .debug)
                log("\(logScope) original HTTP URL: \(sourceURL.absoluteString)", loggingLevel: .debug)
                
                let sourceData: Data
                if let localURL = cachedFileURL(from: url),
                   FileManager.default.fileExists(atPath: localURL.path) {
                    sourceData = try Data(contentsOf: localURL, options: .mappedIfSafe)
                    persistentMediaCacheManager?.touch(fileURL: localURL)
                    log("\(logScope) audio source cache hit, source: \(sourceURL.absoluteString), file: \(localURL.path), bytes: \(sourceData.count)",
                        loggingLevel: .debug)
                } else {
                    sourceData = try await download(url: sourceURL)
                }

                let result = try await transcoder.transcodeAudioSegment(data: sourceData,
                                                                        initializationData: nil,
                                                                        originalCodec: codec,
                                                                        sourceURL: sourceURL)
                guard result.format == .fragmentedMP4, !result.data.isEmpty else {
                    throw UPlayerError.aacEncodongFailed7
                }
                
                dumpTopLevelMP4Boxes(result.data,
                                     prefix: "AAC media")
                
                log("\(logScope) G711 fMP4 \(sourceData.count) -> AAC fMP4 \(result.data.count)", loggingLevel: .debug)
                
                transcodedCache.setObject(result.data as NSData,
                                          forKey: cacheKey,
                                          cost: result.data.count)
                
                respondRedirectedMedia(data: result.data,
                                       realURL: sourceURL,
                                       mimeType: "audio/mp4",
                                       loadingRequest: loadingRequest)
            } catch {
                log("\(logScope) audio transcoding for \(url.absoluteString) failed, \(error)", loggingLevel: .error)
                loadingRequest.finishLoading(with: error)
            }
        }
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func download(url: URL) async throws -> Data {
        var request = URLRequest(url: url,
                                 cachePolicy: .returnCacheDataElseLoad,
                                 timeoutInterval: 30)
        
        for (field, value) in mediaRequestHeader ?? [:]{
            request.setValue(String(describing: value), forHTTPHeaderField: field)
        }
        
        let (data, response) = try await URLSession.shared.data(for: request)
        
        guard let http = response as? HTTPURLResponse else {
            throw UPlayerError.invalidHTTPResponse(-1)
        }
        
        guard (200...299).contains(http.statusCode) else {
            log("\(logScope) HTTP \(http.statusCode), \(url)", loggingLevel: .error)
            throw UPlayerError.invalidHTTPResponse(-1)
        }
        
        log("""
            \(logScope) source download succeeded
            status=\(http.statusCode)
            bytes=\(data.count)
            contentType=\(http.value(forHTTPHeaderField: "Content-Type") ?? "unknown")
            url=\(url.absoluteString)
            """,
            loggingLevel: .debug)
        return data
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func handlePlaylist(url: URL, loadingRequest: AVAssetResourceLoadingRequest) {
        Task { [weak self] in
            guard let self,
                  let playlist = self.dataDelegate?.getPlaylist(source: self, url: url) else {
                loadingRequest.finishLoading(with: UPlayerError.assetLoadingFailed)
                return
            }

            let output: String
            if playlist.contains("mode=cenc-init") || playlist.contains("mode=cenc-segment") {
                guard let baseURL = self.cencProxy.start(
                    processor: self.mediaResourceProcessor,
                    headers: self.mediaRequestHeader
                ) else {
                    loadingRequest.finishLoading(with: UPlayerError.assetLoadingFailed)
                    return
                }
                output = self.cencProxy.rewriteCENCReferences(in: playlist, baseURL: baseURL)
            } else {
                output = playlist
            }

            guard let data = output.data(using: .utf8) else {
                loadingRequest.finishLoading(with: UPlayerError.assetLoadingFailed)
                return
            }
            self.respond(data: data,
                         uti: UTType(filenameExtension: "m3u8")?.identifier ?? "public.m3u-playlist",
                         mimeType: "application/vnd.apple.mpegurl",
                         byteRangeSupported: false,
                         loadingRequest: loadingRequest)
        }
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func respond(data: Data, uti: String, mimeType: String, byteRangeSupported: Bool, loadingRequest: AVAssetResourceLoadingRequest) {
        if let info = loadingRequest.contentInformationRequest{
            info.contentType = uti
            info.contentLength = Int64(data.count)
            info.isByteRangeAccessSupported = byteRangeSupported
        }
        
        if let requestURL = loadingRequest.request.url {
            loadingRequest.response = HTTPURLResponse(url: requestURL,
                                                      statusCode: 200,
                                                      httpVersion: "HTTP/1.1",
                                                      headerFields: [
                                                        "Content-Type": mimeType,
                                                        "Content-Length": "\(data.count)",
                                                        "Accept-Ranges": byteRangeSupported ? "bytes" : "none"
                                                      ])
        }
        
        guard let dataRequest = loadingRequest.dataRequest else {
            loadingRequest.finishLoading()
            return
        }
        
        log("""
            \(logScope) respond
            url=\(loadingRequest.request.url?.absoluteString ?? "nil")
            totalBytes=\(data.count)
            requestedOffset=\(dataRequest.requestedOffset)
            currentOffset=\(dataRequest.currentOffset)
            requestedLength=\(dataRequest.requestedLength)
            requestsAllDataToEnd=\(dataRequest.requestsAllDataToEndOfResource)
            """,
            loggingLevel: .debug)
        
        let start = max(Int(dataRequest.requestedOffset), Int(dataRequest.currentOffset))
        
        guard start >= 0,
            start <= data.count else {
            loadingRequest.finishLoading(with:UPlayerError.assetLoadingFailed)
            return
        }
        
        let available = data.count - start
        let length = dataRequest.requestsAllDataToEndOfResource
            ? available
            : min(dataRequest.requestedLength, available)

        if length > 0 {
            dataRequest.respond(with: data.subdata(in: start..<(start + length)))
        } else if available > 0 {
            loadingRequest.finishLoading(with: UPlayerError.assetLoadingFailed)
            return
        }
        
        loadingRequest.finishLoading()
    }
}

private func dumpTopLevelMP4Boxes(_ data: Data, prefix: String) {
    var offset = 0
    while offset + 8 <= data.count {
        let size = Int(UInt32(data[offset]) << 24 | UInt32(data[offset + 1]) << 16 | UInt32(data[offset + 2]) << 8 | UInt32(data[offset + 3]))
        
        let typeData = data.subdata(in: offset + 4..<offset + 8)
        let type = String(data: typeData, encoding: .ascii) ?? "????"
        
        log("\(logScope) \(prefix) box \(type), offset=\(offset), size=\(size)", loggingLevel: .debug)
        
        guard size >= 8,
                offset + size <= data.count else {
            log("\(logScope) \(prefix) invalid box size \(size) at \(offset)", loggingLevel: .error)
            break
        }
        
        offset += size
    }
    
    if offset != data.count {
        log("\(logScope) \(prefix) unparsed trailing bytes=\(data.count - offset)", loggingLevel: .error)
    }
}

extension UPlayerAVAssetResourceLoader {
    fileprivate func respondRedirectedMedia(data: Data, realURL: URL, mimeType: String, loadingRequest: AVAssetResourceLoadingRequest) {
        var redirectRequest = URLRequest(url: realURL,
                                         cachePolicy: .returnCacheDataElseLoad,
                                         timeoutInterval: 30)
        
        for (field, value) in mediaRequestHeader ?? [:] {
            redirectRequest.setValue(String(describing: value), forHTTPHeaderField: field)
        }

        loadingRequest.redirect = redirectRequest
        let response = HTTPURLResponse(url: realURL,
                                       statusCode: 302,
                                       httpVersion: nil,
                                       headerFields: nil)
        
        loadingRequest.response = response
        if let info = loadingRequest.contentInformationRequest {
            info.contentType = mimeType
            info.contentLength = Int64(data.count)
            info.isByteRangeAccessSupported = false
        }

        log("""
            \(logScope) redirected media response
            requestURL=\(loadingRequest.request.url?.absoluteString ?? "nil")
            redirectURL=\(realURL.absoluteString)
            status=302
            mimeType=\(mimeType)
            bytes=\(data.count)
            requestedOffset=\(loadingRequest.dataRequest?.requestedOffset ?? 0)
            currentOffset=\(loadingRequest.dataRequest?.currentOffset ?? 0)
            requestedLength=\(loadingRequest.dataRequest?.requestedLength ?? 0)
            requestsAllDataToEnd=\(loadingRequest.dataRequest?.requestsAllDataToEndOfResource ?? false)
            """,
            loggingLevel: .debug)
        
        loadingRequest.dataRequest?.respond(with: data)
        loadingRequest.finishLoading()
    }
}


/// AVFoundation requires HTTP(S) delivery for HLS media segments. It rejects
/// segment bytes supplied directly to AVAssetResourceLoader with
/// "custom url not redirect", so ClearKey segments are served by this loopback
/// HTTP endpoint after the CENC processor decrypts them.
private final class LocalCENCProxy {
    private let lock = NSLock()
    private let queue = DispatchQueue(label: "nm7.cenc.loopback", qos: .userInitiated)
    private var listener: NWListener?
    private var port: UInt16?
    private weak var processor: UPlayerMediaResourceProcessor?
    private var headers: [String: Any] = [:]

    func start(processor: UPlayerMediaResourceProcessor?,
               headers: [String: Any]?) -> URL? {
        lock.lock()
        defer { lock.unlock() }
        guard let processor else { return nil }
        self.processor = processor
        self.headers = headers ?? [:]
        if let port {
            return URL(string: "http://127.0.0.1:\(port)")
        }

        let parameters = NWParameters.tcp
        parameters.requiredLocalEndpoint = .hostPort(host: .ipv4(.loopback), port: .any)
        guard let listener = try? NWListener(using: parameters) else { return nil }
        self.listener = listener

        let ready = DispatchSemaphore(value: 0)
        var readyPort: UInt16?
        var failed = false
        listener.stateUpdateHandler = { state in
            switch state {
            case .ready:
                readyPort = listener.port?.rawValue
                ready.signal()
            case .failed:
                failed = true
                ready.signal()
            default:
                break
            }
        }
        listener.newConnectionHandler = { [weak self] connection in
            self?.serve(connection)
        }
        listener.start(queue: queue)
        guard ready.wait(timeout: .now() + 5) == .success,
              !failed, let readyPort else {
            listener.cancel()
            self.listener = nil
            return nil
        }
        self.port = readyPort
        return URL(string: "http://127.0.0.1:\(readyPort)")
    }

    func stop() {
        lock.lock()
        defer { lock.unlock() }
        listener?.cancel()
        listener = nil
        port = nil
        processor = nil
        headers = [:]
    }

    func rewriteCENCReferences(in playlist: String, baseURL: URL) -> String {
        var lines = playlist.components(separatedBy: .newlines)
        for index in lines.indices {
            let line = lines[index]
            if line.hasPrefix("#EXT-X-MAP:"),
               let uriRange = line.range(of: #"URI="[^"]+""#) {
                let quoted = String(line[uriRange])
                let value = String(quoted.dropFirst(5).dropLast())
                if let replacement = proxyURL(for: value, baseURL: baseURL) {
                    lines[index].replaceSubrange(uriRange, with: #"URI="\#(replacement)""#)
                }
            } else if !line.isEmpty, !line.hasPrefix("#"),
                      let replacement = proxyURL(for: line, baseURL: baseURL) {
                lines[index] = replacement
            }
        }
        return lines.joined(separator: "\n")
    }

    private func proxyURL(for value: String, baseURL: URL) -> String? {
        guard let url = URL(string: value),
              let mode = URLComponents(url: url, resolvingAgainstBaseURL: false)?
                .queryItems?.first(where: { $0.name == "mode" })?.value,
              mode == "cenc-init" || mode == "cenc-segment" else {
            return nil
        }
        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else {
            return nil
        }
        if components.scheme?.lowercased() == "uplayer" {
            components.scheme = "https"
        }
        components.queryItems = components.queryItems?.filter {
            $0.name != "mode" && $0.name != "codec" && $0.name != "cacheFile"
        }
        guard let sourceURL = components.url else { return nil }
        let token = Data(sourceURL.absoluteString.utf8).base64EncodedString()
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
        return baseURL.appendingPathComponent("cenc").appendingPathComponent(token).absoluteString
    }

    private func serve(_ connection: NWConnection) {
        connection.start(queue: queue)
        receiveHeader(connection, accumulated: Data())
    }

    private func receiveHeader(_ connection: NWConnection, accumulated: Data) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 16_384) {
            [weak self] data, _, isComplete, error in
            guard let self, error == nil, let data else {
                connection.cancel()
                return
            }
            var bytes = accumulated
            bytes.append(data)
            let delimiter = Data([13, 10, 13, 10])
            guard let end = bytes.range(of: delimiter) else {
                if isComplete || bytes.count > 64 * 1024 {
                    connection.cancel()
                } else {
                    self.receiveHeader(connection, accumulated: bytes)
                }
                return
            }
            let head = String(decoding: bytes[..<end.lowerBound], as: UTF8.self)
            let firstLine = head.components(separatedBy: "\r\n").first ?? ""
            let fields = firstLine.split(separator: " ")
            guard fields.count >= 2,
                  let requestURL = URL(string: "http://127.0.0.1\(fields[1])"),
                  let token = requestURL.pathComponents.last,
                  token != "cenc",
                  let sourceURL = Self.decodeURL(token) else {
                self.send(Data("bad request".utf8), status: 400, on: connection)
                return
            }

            var request = URLRequest(url: sourceURL,
                                     cachePolicy: .reloadIgnoringLocalCacheData,
                                     timeoutInterval: 30)
            self.lock.lock()
            let processor = self.processor
            let requestHeaders = self.headers
            self.lock.unlock()
            requestHeaders.forEach {
                request.setValue(String(describing: $0.value), forHTTPHeaderField: $0.key)
            }
            Task {
                do {
                    let (raw, response) = try await URLSession.shared.data(for: request)
                    if let http = response as? HTTPURLResponse,
                       !(200..<300).contains(http.statusCode) {
                        self.send(Data("upstream HTTP \(http.statusCode)".utf8),
                                  status: 502, on: connection)
                        return
                    }
                    let output = try await processor?.processMediaData(raw,
                                                                       sourceURL: sourceURL,
                                                                       sourceOffset: 0) ?? raw
                    self.send(output, status: 200, on: connection)
                } catch {
                    self.send(Data("CENC proxy failed".utf8), status: 502, on: connection)
                }
            }
        }
    }

    private func send(_ body: Data, status: Int, on connection: NWConnection) {
        let reason = status == 200 ? "OK" : (status == 400 ? "Bad Request" : "Bad Gateway")
        var response = Data("HTTP/1.1 \(status) \(reason)\r\nContent-Type: video/mp4\r\nContent-Length: \(body.count)\r\nAccept-Ranges: none\r\nConnection: close\r\n\r\n".utf8)
        response.append(body)
        connection.send(content: response, completion: .contentProcessed { _ in
            connection.cancel()
        })
    }

    private static func decodeURL(_ token: String) -> URL? {
        var base64 = token.replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        while base64.count % 4 != 0 { base64.append("=") }
        guard let data = Data(base64Encoded: base64),
              let string = String(data: data, encoding: .utf8) else { return nil }
        return URL(string: string)
    }
}
